    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return out
    (a, b), (c, d) = bands[0], bands[-1]
    n = min(b-a, d-c)
    first = [grid[a+i] for i in range(n)]
    second = [grid[d-n+i] for i in range(n)]
    count1 = sum(v != bg for row in first for v in row)
    count2 = sum(v != bg for row in second for v in row)
    if count1 >= count2:
        source, target = first, second
        target_start = d-n
    else:
        source, target = second, first
        target_start = a
    # Find the horizontal translation yielding maximum overlap of foreground pixels.
    best_dx, best_overlap = 0, -1
    for dx in range(-w+1, w):
        overlap = 0
        for y in range(n):
            for x in range(w):
                xx = x + dx
                if 0 <= xx < w and source[y][x] != bg and target[y][xx] != bg:
                    overlap += 1
        if overlap > best_overlap:
            best_overlap, best_dx = overlap, dx
    # Add the template's missing cells to the less complete copy in color 1.
    for y in range(n):
        for x in range(w):
            xx = x + best_dx
            if 0 <= xx < w and source[y][x] != bg and target[y][xx] == bg:
                out[target_start+y][xx] = 1
    return out
